    background-color: var(--bg-color);
    color: var(--text-color);
    margin: 0;
    padding: 2rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    line-height: 1.5;
}

header {
    text-align: center;
    margin-bottom: 3rem;
    max-width: 600px;
}

header h1 {
    font-size: 2.5rem;
    font-weight: 800;
    margin-bottom: 0.5rem;
    color: #111827;
}

header p {
    font-size: 1.125rem;
    color: #6b7280;
}

#faq-container {
    width: 100%;
    max-width: 700px;
    background: var(--card-bg);
    border-radius: 12px;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    overflow: hidden;
    border: 1px solid var(--border-color);
}

.example {
    border-bottom: 1px solid var(--border-color);
}

.example:last-child {
    border-bottom: none;
}

.faq-toggle {
    width: 100%;
    padding: 1.25rem 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    text-align: left;
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--text-color);
    transition: background-color 0.2s ease;
}

.faq-toggle:hover, .faq-toggle:focus {
    background-color: var(--hover-color);
    outline: none;
}

.faq-toggle:focus-visible {
    box-shadow: inset 0 0 0 2px var(--primary-color);
}

.chevron {
    transition: transform 0.3s ease;
    color: #9ca3af;
}

.faq-toggle[aria-expanded="true"] .chevron {
    transform: rotate(180deg);
}

.details {
    padding: 0 1.5rem 1.25rem 1.5rem;
    color: #4b5563;
    font-size: 1rem;
    background-color: #fff;
}

.details[hidden] {
    display: none;
}

footer {
    margin-top: 3rem;
    color: #9ca3af;
    font-size: 0.875rem;
}
